use proc_macro2::{Span,TokenStream,TokenTree};
use quote::ToTokens;
use serde_json::{json,Value};
use std::{collections::{BTreeMap,BTreeSet},fs,path::{Path,PathBuf}};
use syn::{spanned::Spanned,Attribute,Item,Meta,Visibility};
fn requires_test(meta:&Meta)->bool {
 match meta {
  Meta::Path(p)=>p.is_ident("test"),
  Meta::List(l) if l.path.is_ident("all") || l.path.is_ident("any") => {
   let xs=l.parse_args_with(syn::punctuated::Punctuated::<Meta,syn::Token![,]>::parse_terminated).unwrap();
   if l.path.is_ident("all") {xs.iter().any(requires_test)} else {!xs.is_empty()&&xs.iter().all(requires_test)}
  }, _=>false
 }
}
fn only_test(attrs:&[Attribute])->bool {attrs.iter().any(|a|a.path().is_ident("cfg")&&a.parse_args::<Meta>().is_ok_and(|m|requires_test(&m)))}
fn attrs(i:&Item)->&[Attribute] {match i {Item::Const(x)=>&x.attrs,Item::Enum(x)=>&x.attrs,Item::ExternCrate(x)=>&x.attrs,Item::Fn(x)=>&x.attrs,Item::ForeignMod(x)=>&x.attrs,Item::Impl(x)=>&x.attrs,Item::Macro(x)=>&x.attrs,Item::Mod(x)=>&x.attrs,Item::Static(x)=>&x.attrs,Item::Struct(x)=>&x.attrs,Item::Trait(x)=>&x.attrs,Item::TraitAlias(x)=>&x.attrs,Item::Type(x)=>&x.attrs,Item::Union(x)=>&x.attrs,Item::Use(x)=>&x.attrs,_=>&[]}}
fn symbol(i:&Item)->Option<(&syn::Ident,&Visibility)> {match i {Item::Const(x)=>Some((&x.ident,&x.vis)),Item::Enum(x)=>Some((&x.ident,&x.vis)),Item::Fn(x)=>Some((&x.sig.ident,&x.vis)),Item::Mod(x)=>Some((&x.ident,&x.vis)),Item::Static(x)=>Some((&x.ident,&x.vis)),Item::Struct(x)=>Some((&x.ident,&x.vis)),Item::Trait(x)=>Some((&x.ident,&x.vis)),Item::Type(x)=>Some((&x.ident,&x.vis)),Item::Union(x)=>Some((&x.ident,&x.vis)),_=>None}}
fn mark(span:Span,lines:&mut BTreeSet<usize>) {for n in span.start().line..=span.end().line {lines.insert(n);}}
fn idents(tokens:TokenStream,out:&mut BTreeSet<String>) {for t in tokens {match t {TokenTree::Ident(x)=>{out.insert(x.to_string());},TokenTree::Group(g)=>idents(g.stream(),out),_=>()}}}
fn item_links(items:&[Item],dir:&Path,file:&Path,inherited:bool,out:&mut Vec<(PathBuf,bool)>) {
 for i in items {if let Item::Mod(m)=i {let own=inherited||only_test(&m.attrs);if let Some((_,xs))=&m.content {item_links(xs,&dir.join(m.ident.to_string()),file,own,out);} else {
  let explicit=m.attrs.iter().find_map(|a|if a.path().is_ident("path"){if let Meta::NameValue(v)=&a.meta {if let syn::Expr::Lit(x)=&v.value {if let syn::Lit::Str(p)=&x.lit {return Some(file.parent().unwrap().join(p.value()));}}}None}else{None});
  let p=explicit.unwrap_or_else(||{let direct=dir.join(format!("{}.rs",m.ident));if direct.exists(){direct}else{dir.join(m.ident.to_string()).join("mod.rs")}});
  if p.exists(){out.push((p.canonicalize().unwrap(),own));}
 }}}
}
fn walk(items:&[Item],owned:bool,scope:&[String],parent_private:&BTreeSet<String>,lines:&mut BTreeSet<usize>,tests:&mut Vec<Value>) {
 let private:BTreeSet<String>=items.iter().filter(|i|!only_test(attrs(i))).filter_map(symbol).filter(|(_,v)|!matches!(v,Visibility::Public(_))).map(|(s,_)|s.to_string()).collect();
 for i in items {
  let own=owned||only_test(attrs(i));if own {mark(i.span(),lines);}
  if let Item::Fn(f)=i {
   if f.attrs.iter().any(|a|a.path().segments.last().is_some_and(|s|s.ident=="test")) {
    mark(f.span(),lines);
    let mut ids=BTreeSet::new();idents(f.block.to_token_stream(),&mut ids);
    let hits:Vec<_>=ids.intersection(parent_private).cloned().collect();
    tests.push(json!({"name":format!("{}::{}",scope.join("::"),f.sig.ident),"line":f.span().start().line,"private_sibling_name_hits":hits}));
   }
  }
  if let Item::Mod(m)=i {if let Some((_,xs))=&m.content {let mut next=scope.to_vec();next.push(m.ident.to_string());walk(xs,own,&next,&private,lines,tests);}}
 }
}
fn files(dir:&Path,out:&mut Vec<PathBuf>){if !dir.exists(){return;}for p in fs::read_dir(dir).unwrap(){let p=p.unwrap().path();if p.is_dir(){files(&p,out)}else if p.extension().is_some_and(|x|x=="rs"){out.push(p.canonicalize().unwrap())}}}
fn main(){
 let root=std::env::args().nth(1).unwrap();let root=Path::new(&root).canonicalize().unwrap();let mut crates=Vec::new();
 for entry in fs::read_dir(root.join("rs")).unwrap(){let dir=entry.unwrap().path();let lib=dir.join("src/lib.rs");if !lib.exists(){continue;}let mut paths=Vec::new();files(&dir.join("src"),&mut paths);paths.sort();
 let mut parsed=BTreeMap::new();for p in &paths {let source=fs::read_to_string(p).unwrap();let ast=syn::parse_file(&source).unwrap_or_else(|e|panic!("{}: {}",p.display(),e));parsed.insert(p.clone(),(source,ast));}
 let mut seen:BTreeMap<PathBuf,BTreeSet<bool>>=BTreeMap::new();let mut queue=vec![(lib.canonicalize().unwrap(),false)];while let Some((p,only))=queue.pop(){if !seen.entry(p.clone()).or_default().insert(only){continue;}if let Some((_,ast))=parsed.get(&p){let stem=p.file_stem().unwrap().to_str().unwrap();let module_dir=if ["lib","mod","main"].contains(&stem){p.parent().unwrap().to_owned()}else{p.parent().unwrap().join(stem)};item_links(&ast.items,&module_dir,&p,only||only_test(&ast.attrs),&mut queue);}}
 let mut rows=Vec::new();let mut all=0;let mut owned_total=0;let mut count=0;let mut hits=0;
 for (p,(source,ast)) in &parsed {let n=source.lines().count();all+=n;let root_owned=seen.get(p).is_some_and(|s|s.len()==1&&s.contains(&true))||only_test(&ast.attrs);let mut owned=BTreeSet::new();if root_owned {owned.extend(1..=n);}let mut tests=Vec::new();walk(&ast.items,root_owned,&[],&BTreeSet::new(),&mut owned,&mut tests);owned.retain(|x|*x<=n);let h=tests.iter().filter(|t|!t["private_sibling_name_hits"].as_array().unwrap().is_empty()).count();count+=tests.len();hits+=h;owned_total+=owned.len();if !tests.is_empty()||!owned.is_empty(){rows.push(json!({"path":p.strip_prefix(&root).unwrap().display().to_string(),"source_lines":n,"test_owned_lines":owned.len(),"test_functions":tests.len(),"private_sibling_name_hit_tests":h,"tests":tests}));}}
 crates.push(json!({"crate":dir.file_name().unwrap().to_str().unwrap(),"source_files":paths.len(),"source_lines":all,"test_owned_lines":owned_total,"test_functions":count,"private_sibling_name_hit_tests":hits,"files":rows}));}
 crates.sort_by_key(|c|std::cmp::Reverse(c["test_owned_lines"].as_u64().unwrap()));println!("{}",serde_json::to_string_pretty(&crates).unwrap());
}

